// The frames, in order, are the contract - above all for suppression, which retracts.

// One line per frame; entries carry generated timestamps no assertion should read.
const wire = (sent: OutgoingMessage[]): string[] =>
  sent.map(frame => {
    if (frame.type === 'entry_upsert') {
      const content = 'content' in frame.entry ? frame.entry.content : '';
      return `upsert ${frame.index} ${frame.entry.role} ${JSON.stringify(content)}`;
    }
    if (frame.type === 'entry_delta') return `delta ${frame.index} ${JSON.stringify(frame.delta)}`;
    if (frame.type === 'entry_commit') return `commit ${frame.index}`;
    if (frame.type === 'entry_skip') return `skip ${frame.index}`;
    if (frame.type === 'error') return `error ${frame.code}`;
    if (frame.type === 'pong') return `pong ${frame.timestamp}`;
    return frame.type;
  });

const text = (value: string): MessageChunk => ({type: 'text', text: value});
const STOP: MessageChunk = {type: 'stop', stopReason: 'end_turn'};
const SUPPRESS = {type: 'suppress_output'} as unknown as MessageChunk;

interface StreamScript {
  failWith?: Error;
  pauseAfter?: {chunks: number; until: Promise<void>};
  store?: SessionStore;
}

const harness = (chunks: MessageChunk[], {failWith, pauseAfter, store}: StreamScript = {}) => {
  const sent: OutgoingMessage[] = [];
  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;

  const stream = async function* (): AsyncGenerator<MessageChunk> {
    for (const [position, chunk] of chunks.entries()) {
      if (pauseAfter && position === pauseAfter.chunks) await pauseAfter.until;
      yield chunk;
    }
    if (failWith) throw failWith;
  };

  const processMessageStream = jest.fn(stream);
  const orchestrator = {processMessageStream} as unknown as ChatOrchestrator;
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

  const handle = createMessageHandler(orchestrator, store);

  return {
    session,
    processMessageStream,
    sent,
    frames: () => wire(sent),
    send: (raw: unknown = {type: 'user_message', content: 'hello'}, signal?: AbortSignal) =>
      handle(ws, session, raw, signal),
  };
};

describe('the websocket message handler', () => {
  describe('dispatch', () => {
    it('rejects an unparseable message and never starts a stream', async () => {
      const h = harness([]);

      await h.send({type: 'nonsense'});

      const {calls} = h.processMessageStream.mock;

      expect({frames: h.frames(), streams: calls.length}).toEqual({frames: ['error INVALID_MESSAGE'], streams: 0});
    });

    it('answers a ping with the timestamp it was given', async () => {
      const h = harness([]);

      await h.send({type: 'ping', timestamp: 1234});

      expect(h.frames()).toEqual(['pong 1234']);
    });

    it('answers list_sessions from the store for the session user, its times as ISO strings', async () => {
      const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
      const created = new Date('2026-01-01T00:00:00.000Z');
      const updated = new Date('2026-01-01T00:01:00.000Z');
      const store = {
        listFor: (userId: string | number, options?: SessionListOptions) => {
          seen.push({userId, options});
          return [{sessionId: 's0', createdAt: created, updatedAt: updated, entryCount: 2}];
        },
      } as unknown as SessionStore;
      const h = harness([], {store});

      await h.send({type: 'list_sessions', limit: 5, userId: 'u2'});

      expect({seen, sent: h.sent}).toEqual({
        seen: [{userId: 'u1', options: {limit: 5, before: undefined}}],
        sent: [
          {
            type: 'session_list',
            sessions: [
              {sessionId: 's0', createdAt: created.toISOString(), updatedAt: updated.toISOString(), entryCount: 2},
            ],
          },
        ],
      });
    });
  });

  describe('failures', () => {
    it('tells the client to retry when the provider is rate limited', async () => {
      // eslint-disable-next-line re-lint/no-flag-params -- AIError's retryable flag; see adrs/ADR-006-lint-suppressions.md
      const h = harness([], {failWith: new AIError('slow down', 'RATE_LIMITED', true)});

      await h.send();

      expect(h.frames()).toEqual(['upsert 0 user "hello"', 'error RATE_LIMITED', 'stream_end']);
    });

    it('reports any other failure as a server error', async () => {
      const h = harness([], {failWith: new Error('boom')});

      await h.send();

      expect(h.frames()).toEqual(['upsert 0 user "hello"', 'error SERVER_ERROR', 'stream_end']);
    });
  });

  describe('the terminal frame', () => {
71:- An upgrade whose `Host` header is missing or empty (RFC 6455 §4.1 requires one), or whose request-target is not a URL, such as `//`, is answered with HTTP 400 ([validated by: answers an empty Host, a missing Host and a // target with 400 instead of throwing out of the upgrade listener](../../src/transport/malformedUpgrade.test.ts#L68)).
72:- The path check reads the target alone and never throws: a path beginning with `{basePath}/ws` passes, as §2.1 says; any other path, an empty target or `//` fails ([validated by: accepts any path beginning with /hal/ws and refuses another path, an empty target and //, without throwing](../../src/transport/ws/wsPath.test.ts#L4)).
73:- A `WsAuthenticator` that throws synchronously, rather than returning a rejected promise, is answered with HTTP 500, as a rejection is ([validated by: answers 500 when the authenticator throws synchronously instead of rejecting](../../src/transport/malformedUpgrade.test.ts#L82)).
74:- A `WsAuthenticator` that throws or rejects is logged at `error` as `authenticator failed` with its error's type alone, never its message, which can carry the credential it was checking ([validated by: logs a throwing or rejecting authenticator by its error type alone, never its message](../../src/transport/malformedUpgrade.test.ts#L92)).
75:- A `WsAuthenticator` that returns a user directly, not in a promise, is treated like one that resolves to it, rather than failing inside the listener ([validated by: upgrades a request whose authenticator returns a user without a promise](../../src/transport/malformedUpgrade.test.ts#L118)).
76:- A well-formed upgrade is unaffected ([validated by: still upgrades a well-formed request](../../src/transport/malformedUpgrade.test.ts#L126)).
130:Any other field is ignored, and the validator forwards only the fields the frame defines. In particular the server does not read a `chatId` from this message: the connection already determines the session ([validated by: drops any field the frame does not define, rather than forwarding it](../../src/transport/ws/validation.test.ts#L18)).
140:- A session processes one `user_message` at a time, in the order the frames arrived: a frame arriving while an earlier one is still running waits, and its answer starts only after the earlier run's `stream_end` ([validated by: answers a second user_message only after the first has sent its stream_end, in the order they arrived](../../src/transport/ws/messageHandler.test.ts#L675)).
141:- The waiting message's model request therefore holds the earlier answer finished, never one still streaming ([validated by: hands the second run a history whose first answer is finished, never one still streaming](../../src/transport/ws/messageHandler.test.ts#L706)).
142:- A `ping` is answered at once, even while a run is pending ([validated by: answers a ping at once while a run is pending](../../src/transport/ws/messageHandler.test.ts#L724)).
143:- A frame that fails validation and is not a `user_message`, such as a malformed `ping`, gets its `INVALID_MESSAGE` at once, even while a run is pending, but a `user_message` that fails validation is answered in turn, its `INVALID_MESSAGE` and `stream_end` after the run in progress, since an `error` frame names no message and would otherwise read as the running answer's ([validated by: answers an invalid ping at once but an invalid user_message in turn, after the run in progress](../../src/transport/ws/messageHandler.test.ts#L737)).
144:- The reconnect flush (§ 11.3), which sends queued messages in one burst, is therefore safe: they are answered one after another, in the order the user typed them ([validated by: queues three messages sent in one tick before the handler returns, and answers them in that order](../../src/transport/ws/messageHandler.test.ts#L753)).
145:- A queued message whose socket has closed by the time its turn comes is dropped, neither recorded nor answered, since nobody is left to read the answer and a session whose last socket closed has no credentials left ([validated by: drops a queued message whose socket closed before its turn, without asking the model or recording it](../../src/transport/ws/messageHandler.test.ts#L770)).
163:### 4.3 list_sessions
165:Asks for the authenticated user's own conversations, newest activity first. The frame carries no user id: the list is always the connection's user's, and any `userId` a client adds is dropped by the validator rather than forwarded ([validated by: accepts list_sessions with a limit and a before cursor, dropping a client userId](../../src/transport/ws/validation.test.ts#L26)).
169:  "type": "list_sessions",
177:| `type`   | string | Yes      | `"list_sessions"`                                                 |
183:- A `limit` that is not a non-negative integer, or a `before` that is not an object whose `sessionId` is a 1–128 character string and whose `updatedAt` is a string `Date.parse` accepts or a finite number, results in an `error` response with code `INVALID_MESSAGE` ([validated by: rejects a list_sessions whose limit or before cursor is malformed](../../src/transport/ws/validation.test.ts#L34)).
277:Notifies the client that a session entry was created on the server and will never be sent. This happens under output suppression (see [tool-responses.md](../hal-engine-tool-responses/spec.md)): the server keeps the entry so the model retains context, and the client does not need it for display ([validated by: still records a suppressed reply in the session, so history keeps it](../../src/transport/ws/messageHandler.test.ts#L240)).
293:- An entry **opened while suppression is already active** is announced with `entry_skip` and nothing else: no `entry_upsert`, no `entry_delta`, no `entry_commit` follows it ([validated by: skips rather than upserts a segment opened after suppression](../../src/transport/ws/messageHandler.test.ts#L232)).
294:- An entry **already sent before suppression began** cannot be skipped, because the client is displaying it. The server retracts it instead, by re-sending `entry_upsert` at the same index with the entry's `content` set to `""`. The client renders an empty assistant entry as nothing, so the text disappears ([validated by: blanks an assistant entry that was already sent](../../src/transport/ws/messageHandler.test.ts#L209)).
295:- An entry **still streaming when suppression begins** is first committed as streamed so far, with `entry_commit`, and is from then on an entry already sent: an answer is retracted as above, a thought stays as the client saw it, and whatever the model writes next opens a new entry announced with `entry_skip` ([validated by: commits and retracts an answer still open when suppression begins, and skips what follows as a new entry](../../src/transport/ws/messageHandler.test.ts#L296), [validated by: commits a thought still open when suppression begins as the client saw it, and skips what follows](../../src/transport/ws/messageHandler.test.ts#L317)).
299:- Only assistant entries are ever retracted; a thinking entry is never blanked, even when it was sent before suppression began ([validated by: never blanks a thinking entry, only assistant ones](../../src/transport/ws/messageHandler.test.ts#L224)).
300:- Each sent entry is blanked once, so a second suppression in the same stream repeats nothing ([validated by: blanks each sent entry once, so a second suppression repeats nothing](../../src/transport/ws/messageHandler.test.ts#L258)).
301:- An entry the client only ever saw as `entry_skip` is never retracted, because nothing is displayed to retract ([validated by: does not resurrect an entry the client only ever saw skipped](../../src/transport/ws/messageHandler.test.ts#L250)).
340:- A message the server cannot parse into a known type is answered with `INVALID_MESSAGE`, and no message stream is started for it ([validated by: rejects an unparseable message and never starts a stream](../../src/transport/ws/messageHandler.test.ts#L73)).
341:- A rate limit reported by the AI provider is surfaced as `RATE_LIMITED`, which tells the client the same request is worth retrying ([validated by: tells the client to retry when the provider is rate limited](../../src/transport/ws/messageHandler.test.ts#L340)).
342:- Any other failure raised while processing a message is reported as `SERVER_ERROR` ([validated by: reports any other failure as a server error](../../src/transport/ws/messageHandler.test.ts#L349)).
346:Response to a client `ping`. The server MUST echo the client's timestamp without modification ([validated by: answers a ping with the timestamp it was given](../../src/transport/ws/messageHandler.test.ts#L83)).
